 {'file': 'STAR TTW 2.esp',
  'edid': 'SCPTAssetCheckQuest',
  'signature': 'SCPT',
  'old': 'STARS has detected that the required assets from %z are either not active or installed correctly. '
         "Review this mod's section in the installation guide and ensure that you have performed the required "
         'steps before continuing.',
  'new': 'STARS가 %z의 필수 에셋이 활성화되지 않았거나 올바르게 설치되지 않았음을 감지했습니다. 설치 가이드의 해당 모드 섹션을 검토하고 계속하기 전에 필요한 단계를 수행했는지 '
         '확인하십시오.',
  'origin': 'existing_dictionary'},
 {'file': 'STAR TTW 2.esp',
  'edid': 'SCPTAssetCheckQuest',
  'signature': 'SCPT',
  'old': 'STARS has detected that the required assets from Spice Of Life are either not active, they have not '
         "been installed correctly, or they have not been unpacked from their .bsa. Review this mod's section in "
         'the installation guide and ensure that you have performed the required steps before continuing.',
  'new': 'STARS가 Spice Of Life의 필수 에셋이 활성화되지 않았거나, 올바르게 설치되지 않았거나, .bsa 파일에서 압축이 해제되지 않았음을 감지했습니다. 설치 가이드의 해당 모드 '
         '섹션을 검토하고 계속하기 전에 필요한 단계를 수행했는지 확인하십시오.',
  'origin': 'existing_dictionary'},
 {'file': 'STAR TTW 2.esp',
  'edid': 'SCPTStarsGameRestartedStuff',
  'signature': 'SCPT',
  'old': 'The Stewie bDisableStealthEffectInPipboy setting is set to 1, and STARS/Power Armor Holo Panel requires '
         'that it be set to 1 to avoid major clipping and usability issues with the pipboy in power armor. Set '
         'this to 0 and restart the game before continuing.',
  'new': 'Stewie의 bDisableStealthEffectInPipboy 설정이 1로 되어 있습니다. STARS/파워 아머 홀로 패널은 파워 아머 착용 시 핍보이의 심각한 클리핑 및 사용성 '
         '문제를 방지하기 위해 이 설정을 1로 유지해야 합니다. 이 설정을 0으로 변경하고 게임을 재시작한 후 계속하십시오.',
  'origin': 'existing_dictionary'},
 {'file': 'STAR TTW 2.esp',
  'edid': 'SCPTStarsGameRestartedStuff',
  'signature': 'SCPT',
  'old': 'The JIP uNPCPerks setting was set to 0, and STARS requires that it be set to 1 or 2. It has been set to '
         '1 by script, but you must close the game and restart before continuing.',
  'new': 'JIP의 uNPCPerks 설정이 0으로 되어 있습니다. STARS는 이 설정을 1 또는 2로 요구합니다. 스크립트를 통해 1로 변경되었으나, 게임을 종료하고 재시작한 후 계속해야 '
         '합니다.',
  'origin': 'existing_dictionary'},
 {'file': 'NS.esm',
  'edid': 'SCPTStarsFirstTimeMessages',
  'signature': 'SCPT',
  'old': "You've picked up a Tank Helmet. The visor on the helmet can be raised or lowered by pressing the Grab "
         'key while the helmet is selected in the Pip-Boy, which will allow for masks and glasses to be worn '
         'while the visor is up.',
  'new': '탱크 헬멧을 획득했습니다. 핍보이에서 헬멧을 선택한 상태로 잡기 키를 누르면 바이저를 올리거나 내릴 수 있으며, 바이저를 올리면 마스크와 안경을 착용할 수 있습니다.',
  'origin': 'existing_dictionary'},
 {'file': 'NS.esm',
  'edid': 'SCPTStarsFirstTimeMessages',
  'signature': 'SCPT',
  'old': "You've equipped a gas mask, helmet, radiation suit, or similar item that helps block radiation that you "
         'breathe in. The condition of these items will degrade while you are standing in irradiated areas, and '
         'this penalty will be increased while walking, and further while running.',
  'new': '호흡기 방사능을 차단하는 데 도움이 되는 방독면, 헬멧, 방사능 보호복 또는 유사한 장비를 착용했습니다. 이 장비들의 상태는 방사능 구역에 서 있을 때 저하되며, 걸을 때는 저하 속도가 '
         '빨라지고 달릴 때는 더욱 빨라집니다.',
  'origin': 'existing_dictionary'},
 {'file': 'NS.esm',
  'edid': 'SCPTStarsFirstTimeMessages',
  'signature': 'SCPT',
  'old': "You've equipped a backpack. Backpacks naturally grant substantially increased carry weight, but they "
         'also reduce your AP regeneration speed. They often also have stat maluses, which will be reduced as '
         'your Survival skill increases.',
  'new': '배낭을 착용했습니다. 배낭은 기본적으로 소지 중량을 크게 늘려주지만, AP 재생 속도를 감소시킵니다. 또한 생존 기술이 높아질수록 감소하는 능력치 페널티가 있는 경우가 많습니다.',
  'origin': 'existing_dictionary'},
 {'file': 'NS.esm',
  'edid': 'SCPTStarsFirstTimeMessages',
  'signature': 'SCPT',
  'old': "You've equipped an item that supports enhanced vision modes. These items are powered by Small Energy "
         'Cells through your Pip-Boy, which maintains a universal charge for all vision modes. To use the vision '
         'modes, hold N to engage or disengage them. While engaged, tap N to switch between night vision and '
         'thermal vision.',
  'new': '향상된 시야 모드를 지원하는 장비를 착용했습니다. 이 장비는 핍보이를 통해 소형 에너지 셀의 전력을 공급받으며, 모든 시야 모드에 대해 통합된 전력을 유지합니다. 시야 모드를 사용하려면 '
         'N 키를 길게 눌러 활성화하거나 비활성화하십시오. 활성화된 상태에서 N 키를 짧게 누르면 야간 투시와 열 감지 모드 사이를 전환할 수 있습니다.',
  'origin': 'existing_dictionary'},
 {'file': 'NS.esm',
  'edid': 'SCPTStarsFirstTimeMessages',
  'signature': 'SCPT',
  'old': 'You have received the specialized training needed to move in any form of Power Armor.',
  'new': '파워 아머를 자유롭게 움직이는 데 필요한 전문 훈련을 받았습니다.',
  'origin': 'existing_dictionary'},
