 {'file': '[#] [INF] - Nuclear Sunset Normal Difficulty Lock/nvse/plugins/Scripts/ln_NormalLock.txt',
  'edid': 'ln_NormalLock',
  'signature': 'loose',
  'old': 'Nuclear Sunset only offically supports the normal difficulty, regardless of the presence of mods which '
         'alter difficuly modifier values. The difficulty has been reset to normal. This forced change can be '
         'stopped  by disabling NS Normal Difficulty Lock, but it voids support and your balance feedback for the '
         'list.',
  'new': 'Nuclear Sunset은 난이도 수정 값을 변경하는 모드 사용 여부와 관계없이 보통 난이도만 공식 지원합니다. 난이도가 보통으로 재설정되었습니다. 이 강제 변경은 NS Normal '
         'Difficulty Lock을 비활성화하여 멈출 수 있으나, 이 경우 모드 목록에 대한 지원 및 밸런스 피드백을 받을 수 없습니다.',
  'origin': 'existing_dictionary'},
 {'file': '[#] [INF] - Nuclear Sunset Normal Difficulty Lock/nvse/plugins/Scripts/ln_NormalLock.txt',
  'edid': 'ln_NormalLock',
  'signature': 'loose',
  'old': 'Nuclear Sunset only supports normal difficulty, regardless of the use of mods which alter difficulty '
         'damage modifier values. The difficulty has been reset to normal. This forced change can be stopped by '
         'disabling NS Normal Difficulty Lock, but it voids support and your balance feedback for the list.',
  'new': 'Nuclear Sunset은 난이도 피해 수정 값을 변경하는 모드 사용 여부와 관계없이 보통 난이도만 지원합니다. 난이도가 보통으로 재설정되었습니다. 이 강제 변경은 NS Normal '
         'Difficulty Lock을 비활성화하여 멈출 수 있으나, 이 경우 모드 목록에 대한 지원 및 밸런스 피드백을 받을 수 없습니다.',
  'origin': 'existing_dictionary'},
