 {'file': 'FreePostMojave.esm',
  'edid': 'ExpressExpansion1',
  'signature': 'SCPT',
  'old': '^The Mojave Express is Expanding!^The Mojave Express is expanding into several new locations across the '
         "wasteland!%r%rAs a thanks for being a loyal customer and former employee - we're giving you access to "
         'these boxes for free. There are new shipping destinations for the following locations:%r%r- Sloan%r- '
         '188 Trading Post%r- Boulder City%r- HELIOS One%r- Mojave Outpost',
  'new': '^모하비 익스프레스 확장!^황무지 곳곳에 새 우편함을 설치했습니다!%r%r오랜 고객이자 전 직원이신 귀하께 감사드리며, 다음 목적지의 우편함을 무료로 개방합니다.%r%r- 슬론%r- '
         '188 교역소%r- 볼더 시티%r- 헬리오스 원%r- 모하비 초소',
  'origin': 'reviewed_composed_message'},
 {'file': 'FreePostMojave.esm',
  'edid': 'ExpressExpansion2',
  'signature': 'SCPT',
  'old': '^The Mojave Express is Expanding!^Greetings Wastelander!%r%rThe Mojave Express has finally reached its '
         "goal of expanding even further into the wastes. As an owner of all five core stamps, we're giving you a "
         'stampbook, and access to our new boxes free of charge!%r%rNew Boxes are located at:%r%r- Crimson '
         "Caravan Company%r- Gun Runners HQ%r- Westside%r- North Vegas%r- Jacobstown%r- Grub n' Gulp%r- Field's "
         'Shack',
  'new': '^모하비 익스프레스 확장!^안녕하세요, 황무지 주민 여러분!%r%r모하비 익스프레스가 더 먼 황무지까지 진출했습니다. 핵심 우표 다섯 종을 모두 모으신 귀하께 우표첩을 드리고 새 '
         '우편함을 무료로 개방합니다!%r%r새 우편함 위치:%r%r- 크림슨 캐러밴 회사%r- 건 러너스 본부%r- 웨스트사이드%r- 노스 베가스%r- 제이콥스타운%r- 그럽 앤 걸프%r- '
         '필즈의 판잣집',
  'origin': 'reviewed_composed_message'},
 {'file': 'FreePostMojave.esm',
  'edid': 'MojaveFreepostIntroGoodsprings',
  'signature': 'SCPT',
  'old': "^Mojave Express Dropbox - Goodsprings^This is a Mojave Express Dropbox. It's old and weathered - but "
         'still sturdy.%r%r',
  'new': '^모하비 익스프레스 우편함 - 굿스프링스^낡고 풍화됐지만 아직 튼튼한 모하비 익스프레스 우편함입니다.%r%r',
  'origin': 'reviewed_composed_message'},
 {'file': 'FreePostMojave.esm',
  'edid': 'MojaveFreepostIntroPrimm',
  'signature': 'SCPT',
  'old': '^Mojave Express Dropbox - Primm^The once striking paint on this dropbox has since been eroded by time, '
         'nuclear radiation, and the sandy Nevada wind.%r%rThis tiny town, tucked against a rollercoaster, has '
         'been besieged by bandits. The Sheriff was murdered in his own bed.%r%rThe world may have survived the '
         "nuclear holocaust, but so has mankind's propensity for violence.",
  'new': '^모하비 익스프레스 우편함 - 프림^한때 선명했던 칠은 세월과 방사능, 네바다의 모래바람에 벗겨졌습니다.%r%r롤러코스터 옆 이 작은 마을은 도적들에게 포위됐고, 보안관은 자기 침대에서 '
         '살해됐습니다.%r%r세상은 핵전쟁을 견뎌 냈지만 인류의 폭력성도 살아남았습니다.',
  'origin': 'reviewed_composed_message'},
 {'file': 'FreePostMojave.esm',
  'edid': 'MojaveFreepostIntroNovac',
  'signature': 'SCPT',
  'old': '^Mojave Express Dropbox - Novac^The lid to this dropbox appears to be in fairly poor condition. After '
         'prying at the corners of the rusted lid, the rust breaks free, granting you a slim ray of light into '
         'the empty bin.%r%rThe dropbox is in much the same condition as Novac - ailing and run-down.',
  'new': '^모하비 익스프레스 우편함 - 노박^뚜껑 상태가 몹시 나쁩니다. 녹슨 모서리를 비집자 녹이 떨어져 나가고 빈 통 안으로 가느다란 빛이 듭니다.%r%r노박처럼 이 우편함도 쇠락하고 '
         '낡았습니다.',
  'origin': 'reviewed_composed_message'},
 {'file': 'FreePostMojave.esm',
  'edid': 'MojaveFreepostIntroFreeside',
  'signature': 'SCPT',
  'old': '^Mojave Express Dropbox - Freeside^This dropbox is in decent shape. Perhaps the Followers of the '
         'Apocalypse maintain it',
  'new': '^모하비 익스프레스 우편함 - 프리사이드^상태가 양호합니다. 묵시록의 추종자들이 관리하는 듯합니다.',
  'origin': 'reviewed_composed_message'},
 {'file': 'FreePostMojave.esm',
  'edid': 'MojaveFreepostIntroStrip',
  'signature': 'SCPT',
  'old': '^Mojave Express Dropbox - The Strip^Blinding lights. Deafening music. Another reminder of the past. '
         'This box is in fantastic condition and is well maintained.%r%r',
  'new': '^모하비 익스프레스 우편함 - 스트립^눈부신 불빛과 귀를 울리는 음악이 과거를 떠올리게 합니다. 우편함은 관리가 잘되어 상태가 훌륭합니다.%r%r',
  'origin': 'reviewed_composed_message'},
 {'file': 'FreePostMojave.esm',
  'edid': 'MojaveFreepostIntroNipton',
  'signature': 'SCPT',
  'old': "^Mojave Express Dropbox - Nipton^This dropbox has been heavily vandalized. It's totally "
         "unusable.%r%rIt's unlikely that Couriers venture this far, especially considering the scene you just "
         'witnessed.%r%rThe air is filled with smoke, pained groaning, and bright red fires, slowly burning the '
         'once prosperous town of Nipton to the ground. The smell of charred remains and burnt hair lingers in '
         "your nostrils.%r%rIt's probably best to not stick around.",
  'new': '^모하비 익스프레스 우편함 - 닙튼^심하게 파손되어 사용할 수 없습니다.%r%r방금 본 광경을 생각하면 배달부가 여기까지 올 것 같지 않습니다.%r%r연기와 신음이 공기를 채우고, 붉은 '
         '불길이 번성했던 닙튼을 천천히 잿더미로 만듭니다. 탄 시체와 머리카락 냄새가 코에 맴돕니다.%r%r오래 머물지 않는 편이 좋겠습니다.',
  'origin': 'reviewed_composed_message'},
